// Max user display screens per mode, by variant codename. Android's equivalent of
// custom_modes.py's max_displays_for_variant (_MAX_DISPLAYS_BY_VARIANT = {Jabiru:4, Loon:4},
// default 8). This isn't a field in the captured VariantLimits above (SuuntoLink derives it in
// JS), so it's kept as its own small table. Traverse (Jabiru) and Traverse Alpha (Loon) = 4;
// the rest of the Ambit3 family = 8. André, 2026-08-17.
const MAX_DISPLAYS_BY_VARIANT: Record<string, number> = { Jabiru: 4, Loon: 4 };
export function maxDisplaysForVariant(variant?: string): number {
  return (variant && MAX_DISPLAYS_BY_VARIANT[variant]) || 8;
}
